fail() { printf 'Cannot hand over: %s\n' "$1" >&2; exit 2; }
if test "$#" -gt 1; then fail 'too many arguments'; fi
mode=${1-preview}
case "$mode" in preview|publish) : ;; *) fail 'choose preview or publish' ;; esac
if test -z "$NAME1"; then fail 'first job name is empty'; fi
if test -z "$NAME2"; then fail 'second job name is empty'; fi
base_team=${BASE_TEAM:-Operations}
base_note=${BASE_NOTE-Ready}
resolve() {
 local label=$1 team_given=$2 own_team=$3 note_given=$4 own_note=$5 position=$6
 local team=$base_team note=$base_note
 if test -n "$team_given"; then team=$own_team; fi
 if test -n "$note_given"; then note=$own_note; fi
 if test -z "$team"; then printf 'Cannot hand over: %s job team is empty\n' "$position" >&2; return 2; fi
 printf 'Job: %s\nTeam: %s\nNote: %s\n' "$label" "$team" "$note"
}
if first=$(resolve "$NAME1" "${TEAM1+set}" "$TEAM1" "${NOTE1+set}" "$NOTE1" first); then :; else exit 2; fi
if second=$(resolve "$NAME2" "${TEAM2+set}" "$TEAM2" "${NOTE2+set}" "$NOTE2" second); then :; else exit 2; fi
report="$first

$second
